package com.bank.spark.model;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

// Holds which account ids fall in which bucket for one table.
public class BucketLayout {
    private final int numBuckets;
    private final Map<Integer, List<String>> buckets = new TreeMap<>();

    public BucketLayout(int numBuckets) {
        this.numBuckets = numBuckets;
    }

    public int bucketOf(String accountId) {
        return Math.floorMod(accountId.hashCode(), numBuckets);
    }

    public void add(String accountId) {
        buckets.computeIfAbsent(bucketOf(accountId), k -> new ArrayList<>()).add(accountId);
    }

    public List<String> bucket(int b) { return buckets.getOrDefault(b, List.of()); }
    public Map<Integer, List<String>> all() { return buckets; }
    public int getNumBuckets() { return numBuckets; }
}
