package com.bank.spark.service;

import com.bank.spark.model.BucketLayout;

import java.util.ArrayList;
import java.util.List;

// Simulates the three bucket optimizations.
public class BucketQueryEngine {

    // Bucket pruning: equality filter touches exactly one bucket.
    public int prune(BucketLayout layout, String accountId) {
        return layout.bucketOf(accountId);   // the only bucket to read
    }

    // Shuffle-free aggregation: group within each bucket, no exchange.
    public List<String> aggregatePerBucket(BucketLayout layout) {
        List<String> plan = new ArrayList<>();
        layout.all().forEach((b, accts) ->
                plan.add("bucket " + b + ": group " + accts + " locally (no shuffle)"));
        return plan;
    }

    // Bucket-aware join: pair same-numbered buckets, no shuffle.
    public List<String> join(BucketLayout left, BucketLayout right) {
        if (left.getNumBuckets() != right.getNumBuckets()) {
            throw new IllegalStateException("Bucket counts differ -> shuffle required");
        }
        List<String> plan = new ArrayList<>();
        for (int b = 0; b < left.getNumBuckets(); b++) {
            if (!left.bucket(b).isEmpty() || !right.bucket(b).isEmpty()) {
                plan.add("join left[" + b + "] with right[" + b + "] (no shuffle)");
            }
        }
        return plan;
    }
}
