package com.bank.spark;

import com.bank.spark.model.BucketLayout;
import com.bank.spark.service.BucketQueryEngine;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BucketOptimizeDemo {

    private static final Logger log = Logger.getLogger(BucketOptimizeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BucketQueryEngine engine = new BucketQueryEngine();

        BucketLayout txns = new BucketLayout(8);
        BucketLayout accts = new BucketLayout(8);
        String[] ids = {"SAV2001", "CUR3001", "SAV2002", "CUR3002", "SAV2003"};
        for (String id : ids) { txns.add(id); accts.add(id); }

        // 1) Bucket pruning
        int bucket = engine.prune(txns, "SAV2001");
        log.info(() -> "Bucket pruning: WHERE accountId='SAV2001' reads ONLY bucket " + bucket
                + " of " + txns.getNumBuckets() + " (7 skipped)");

        // 2) Shuffle-free aggregation
        log.info("Shuffle-free aggregation (groupBy accountId):");
        engine.aggregatePerBucket(txns).forEach(log::info);

        // 3) Bucket-aware join
        log.info("Bucket-aware join (transactions JOIN accounts ON accountId):");
        engine.join(txns, accts).forEach(log::info);

        log.info("All three avoided the expensive shuffle by exploiting the bucket invariant.");
    }
}

